SELECT Owners.owner_id, Owners.first_name, Owners.last_name, Owners.street, Owners.city, Owners.state, Owners.zip_code, Owners.email_address, Owners.home_phone, Owners.cell_number, Dogs.name, Dogs.age, Dogs.date_of_birth, Dogs.gender, Dogs.date_arrived, Dogs.date_departed, Dogs.date_adopted, Dogs.date_departed
FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id
WHERE Dogs.abandoned_yn = 'Y' AND Dogs.date_departed IS NOT NULL;
